package com.campusiq.platform.strategy; import com.campusiq.platform.client.CodeChefClient; import com.campusiq.platform.dto.PlatformProfileResponse; import com.campusiq.platform.entity.Platform; import org.springframework.stereotype.Component; @Component public class CodeChefStrategy implements PlatformProfileStrategy {private final CodeChefClient c; public CodeChefStrategy(CodeChefClient x){c=x;} public Platform getPlatform(){return Platform.CODECHEF;} public boolean verifyUser(String u){try{return c.profile(u)!=null;}catch(Exception e){return false;}} public PlatformProfileResponse fetchProfile(String u){var p=c.profile(u);Double rating=p.rating()==null?null:p.rating().doubleValue();return new PlatformProfileResponse(getPlatform(),u,"https://www.codechef.com/users/"+u,null,null,p.globalRank(),null,p.totalSolved()==null?null:p.totalSolved().intValue(),null,null,null,rating,null,null,rating,null,null,null,null,p.countryRank(),p.stars());}}
